function handle(event) {
  const errors = [];
  if (typeof event.tenantId !== 'string' || event.tenantId.trim().length < 2) errors.push('tenantId');
  if (typeof event.eventId !== 'string' || event.eventId.trim().length < 4) errors.push('eventId');
  if (!['web', 'whatsapp', 'internal_test'].includes(event.channel)) errors.push('channel');
  if (typeof event.message !== 'string' || !event.message.trim() || event.message.length > 4000) errors.push('message');
  if (event.authenticatedByBackend !== true) errors.push('backend_authentication');

  if (errors.length) return { ok: false, error: 'invalid_or_untrusted_event', missing: errors, actionProposal: null };

  const text = event.message.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  let intent = 'other';
  let proposedAction = 'ask_clarifying_question';
  let needsHuman = false;

  if (/\b(persona|humano|asesor|administrador|hablar con alguien)\b/.test(text)) { intent = 'human_handoff'; proposedAction = 'handoff_to_business'; needsHuman = true; }
  else if (/\b(cancelar|cambiar|reagendar|mover mi cita|modificar cita)\b/.test(text)) { intent = 'appointment_change'; proposedAction = 'request_appointment_lookup'; }
  else if (/\b(cita|turno|reservar|agendar|disponibilidad|horario para)\b/.test(text)) { intent = 'appointment_request'; proposedAction = 'request_availability_lookup'; }
  else if (/\b(historial|ultima vez|ultima visita|referencia|que me hice)\b/.test(text)) { intent = 'customer_history'; proposedAction = 'request_customer_context'; }
  else if (/\b(producto|stock|inventario|precio|cuesta|venden)\b/.test(text)) { intent = 'product_question'; proposedAction = 'request_catalog_lookup'; }
  else if (/\b(horario|direccion|ubicacion|servicio|atienden|abren)\b/.test(text)) { intent = 'business_information'; proposedAction = 'request_public_business_info'; }

  return {
    ok: true, tenantId: event.tenantId, eventId: event.eventId, channel: event.channel,
    intent, actionProposal: { type: proposedAction, requiresBackendAuthorization: true, execute: false },
    needsHuman, messageForCustomer: null,
    controls: { noBookingCreated: true, noCustomerRecordRead: true, noInventoryChanged: true, noMessageSent: true }
  };
}
return [{ json: handle($input.first().json) }];
